{"results": [{"id": "hp_doc_aff6990e5fae6798259482fc368a4bf73d08591bedafda186a08203adeefac3d", "title": "Mike Carey (basketball)", "text": "Michael Alan Carey (born July 4, 1958) is the current head coach of the West Virginia University women's basketball team. He had previously served as head basketball coach for the Salem International University men's basketball team.", "score": 32.059}, {"id": "hp_doc_e0df0bd2dea915276a095fa937fd2a15ad456562aa7a8fda26513537b181045c", "title": "West Virginia Mountaineers women's basketball", "text": "The West Virginia Mountaineers women's basketball team represents West Virginia University in NCAA Division I college basketball competition. They are a member of the Big 12 Conference. West Virginia has earned eight bids to the NCAA Women's Division I Basketball Championship, led by West Virginia coach and former WVU player Mike Carey. Most recently, they won the 2017 Big 12 Tournament, despite finishing sixth in the regular season.", "score": 24.0348}, {"id": "hp_doc_b43d0d5ac0fef0a93a41473c4280c13ea64d066614ecee95fd5188515c6b9f72", "title": "Hank Egan", "text": "Henry Patrick \"Hank\" Egan Jr. (born August 17, 1937) is a professional basketball coach in the National Basketball Association. He has most recently served as an assistant coach for the Cleveland Cavaliers (to Mike Brown). He has also been an assistant with the Golden State Warriors (to Eric Musselman) and San Antonio Spurs (to Gregg Popovich).", "score": 18.7199}], "remaining_searches": 2}
