Controller result:
{"results": [{"id": "hp_doc_ffc105c438b34d4f6e2d7ce2901c7c971df5abeaebf1ec58041a104030c09c74", "title": "West Virginia University", "text": "West Virginia University (WVU) is a public, land-grant, space-grant, research-intensive university in Morgantown, West Virginia, United States. Its other campuses include the West Virginia University Institute of Technology in Montgomery and Potomac State College of West Virginia University in Keyser; and a second clinical campus for the University's medical and dental schools at Charleston Area Medical Center in Charleston. WVU Extension Service provides outreach with offices in all of West Virginia's 55 counties. Since 2001, WVU has been governed by the West Virginia University Board of Governors.", "score": 21.7924}, {"id": "hp_doc_e0df0bd2dea915276a095fa937fd2a15ad456562aa7a8fda26513537b181045c", "title": "West Virginia Mountaineers women's basketball", "text": "The West Virginia Mountaineers women's basketball team represents West Virginia University in NCAA Division I college basketball competition. They are a member of the Big 12 Conference. West Virginia has earned eight bids to the NCAA Women's Division I Basketball Championship, led by West Virginia coach and former WVU player Mike Carey. Most recently, they won the 2017 Big 12 Tournament, despite finishing sixth in the regular season.", "score": 19.0278}, {"id": "hp_doc_1761fd84e2b6c8ea74e87f024c072712493eee24fa5a1b381c65b35f2556e370", "title": "2011 West Virginia Mountaineers football team", "text": "The 2011 West Virginia Mountaineer football team represented West Virginia University in the 2011 NCAA Division I FBS football season as members of the Big East Conference. The Mountaineers were led by Dana Holgorsen, who was his first season as head coach. West Virginia played their home games on Mountaineer Field at Milan Puskar Stadium in Morgantown, West Virginia. They finished the season 10–3, 5–2 in Big East play to earn a share of the Big East Conference championship with Cincinnati and Louisville. The Mountaineers earned the league's automatic berth in the BCS due to being the highest ranked of the Big East champions in the final BCS rankings. They were invited to the Orange Bowl for the first time ever where they defeated Clemson 70–33. West Virginia is now 3–0 in BCS games and the 70 points in the Orange Bowl is the most points ever scored by one team in a bowl game.", "score": 16.3767}], "remaining_searches": 1}
